<script lang="ts">
	import classNames from 'classnames';
	export let tag: 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6' = 'h1';
	export let color: string = 'text-gray-brand-2 dark:text-gray-brand-4';
	export let customSize: string = '';
	export let hClass: string = 'font-header leading-[1.27] font-bold mb-4';
	export let classes: string = '';
	// export {classes as class};
	const textSizes = {
		h1: 'text-5xl font-extrabold',
		h2: 'text-4xl font-bold',
		h3: 'text-3xl font-bold',
		h4: 'text-2xl font-bold',
		h5: 'text-xl font-bold',
		h6: 'text-lg font-bold'
	};
</script>

<svelte:element
	this={tag}
	{...$$restProps}
	class={classNames(
		customSize ? customSize : textSizes[tag],
		color,
		hClass,
		classes,
		'w-full',
		$$props.class
	)}
>
	<slot />
</svelte:element>
